{"implementation":"def solve(case):
    # validate
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError("Missing required fields")
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {}
    children_map = {}
    for node in nodes:
        for key in ['id','parent','symbol','depth','removable','utility']:
            if key not in node:
                raise ValueError("Node missing field " + key)
        nid = node['id']
        parent = node['parent']
        if nid in node_map:
            raise ValueError("Duplicate node id")
        node_map[nid] = node
        if parent is not None:
            children_map.setdefault(parent, []).append(nid)
    root_id = None
    for nid, nod in node_map.items():
        if nod['parent'] is None:
            if root_id is not None:
                raise ValueError("Multiple roots")
            root_id = nid
    if root_id is None:
        raise ValueError("No root node")
    for nid, nod in node_map.items():
        if nod['parent'] is not None and nod['parent'] not in node_map:
            raise ValueError("Parent not found")
    retained = set(node_map.keys())
    candidates = [(nod['depth'], nid) for nid, nod in node_map.items()]
    candidates.sort(key=lambda x: (-x[0], x[1]))
    removal_order = []
    for _, nid in candidates:
        if nid not in retained:
            continue
        nod = node_map[nid]
        if not nod['removable']:
            continue
        if nid == root_id:
            continue
        if nod['symbol'] in required_symbols:
            continue
        children = children_map.get(nid, [])
        if any(cid in retained for cid in children):
            continue
        rem_symbols = set()
        for rid in retained:
            if rid == nid:
                continue
            rem_symbols.add(node_map[rid]['symbol'])
        if required_symbols.issubset(rem_symbols):
            retained.remove(nid)
            removal_order.append(nid)
    retained_ids = sorted(retained)
    return {"retained_ids": retained_ids, "removal_order": removal_order}"}
